import re

def main(inp):
    text = '\n'.join(inp.get('files', {}).values())
    kws = ['meta.option', 'stronger result', 'strictly stronger',
           'unlisted', 'stronger theorem', 'stronger unlisted']
    n = sum(len(re.findall(k, text, re.I)) for k in kws)
    sup = len(re.findall(r'(?i)meta.option.{0,80}(?:correct|applies|favored|strong candidate|is the answer|best candidate)', text))
    dis = len(re.findall(r'(?i)meta.option.{0,80}(?:unlikely|unjustified|no basis|eliminated|not apply|incorrect|no.*stronger)', text))
    if sup > dis and n >= 5:
        s = f'STRONG META-OPTION SUPPORT: {n} references across notes, {sup} supporting vs {dis} dismissing. The analysis found substantial evidence for a stronger unlisted result. Give the meta-option serious weight.'
    elif n >= 3:
        s = f'MODERATE META-OPTION EVIDENCE: {n} references, {sup} supporting vs {dis} dismissing. Review the meta-option argument carefully.'
    else:
        s = f'LIMITED META-OPTION EVIDENCE: {n} references. Concrete options likely contain the answer.'
    return {'facts': {'meta_signal': s}}

